assert("AsPointer");
assert("As");
assert("AsRef");
assert("Add");
assert("AddByteOffset");
assert("Copy");
assert("CopyBlock");
assert("CopyBlockUnaligned");
assert("InitBlock");
assert("InitBlockUnaligned");
assert("Read");
assert("Write");
assert("ReadUnaligned");
assert("WriteUnaligned");
assert("AreSame");
assert("ByteOffset");
assert("NullRef");
assert("IsNullRef");
assert("SkipInit");
assert("Subtract");
assert("SubtractByteOffset");
assert("Unbox");

assert(null, "default");
assert("", "default");
assert("other", "default");
System.Console.Write("RAN");

void assert(string input, string expected = null)
{
    if (C.M(input) != (expected ?? input))
    {
        throw new System.Exception($"{input} produced {C.M(input)}");
    }
}

public class C
{
    public static string M(string value)
    {
        return value switch
        {
            "AsPointer" => "AsPointer",
            "As" => "As",
            "AsRef" => "AsRef",
            "Add" => "Add",
            "AddByteOffset" => "AddByteOffset",
            "Copy" => "Copy",
            "CopyBlock" => "CopyBlock",
            "CopyBlockUnaligned" => "CopyBlockUnaligned",
            "InitBlock" => "InitBlock",
            "InitBlockUnaligned" => "InitBlockUnaligned",
            "Read" => "Read",
            "Write" => "Write",
            "ReadUnaligned" => "ReadUnaligned",
            "WriteUnaligned" => "WriteUnaligned",
            "AreSame" => "AreSame",
            "ByteOffset" => "ByteOffset",
            "NullRef" => "NullRef",
            "IsNullRef" => "IsNullRef",
            "SkipInit" => "SkipInit",
            "Subtract" => "Subtract",
            "SubtractByteOffset" => "SubtractByteOffset",
            "Unbox" => "Unbox",
            _ => "default"
        };
    }
}
